/**
 * Browser polyfill for Chromium-based browsers (Edge/Chrome) — Manifest V3.
 * Wraps chrome.* callback APIs into promise-based browser.* namespace,
 * compatible with Mozilla's WebExtension API used throughout this extension.
 */
(function() {
  "use strict";

  if (typeof globalThis.browser === "undefined" || Object.getPrototypeOf(globalThis.browser) !== Object.prototype) {
    const chrome = globalThis.chrome;

    /**
     * Wraps a Chrome API method that uses a callback into one returning a
     * Promise.  If the method already returns a Promise (as some MV3 APIs do),
     * that Promise is returned directly.
     */
    function wrapAsyncFunction(method, target) {
      return function(...args) {
        try {
          // MV3 chrome.* APIs may already return Promises — try that first.
          const maybePromise = method.apply(target, args);
          if (maybePromise && typeof maybePromise.then === "function") {
            return maybePromise;
          }
        } catch (_) {
          // Falls through to callback wrapping below.
        }

        return new Promise((resolve, reject) => {
          method.call(target, ...args, function(...results) {
            if (chrome.runtime.lastError) {
              reject(new Error(chrome.runtime.lastError.message));
            } else {
              resolve(results.length <= 1 ? results[0] : results);
            }
          });
        });
      };
    }

    const browserObj = {};

    // runtime
    if (chrome.runtime) {
      browserObj.runtime = {
        sendMessage: wrapAsyncFunction(chrome.runtime.sendMessage, chrome.runtime),
        onMessage: chrome.runtime.onMessage,
        onInstalled: chrome.runtime.onInstalled,
        getURL: chrome.runtime.getURL.bind(chrome.runtime),
        getManifest: chrome.runtime.getManifest.bind(chrome.runtime),
        get lastError() { return chrome.runtime.lastError; },
        get id() { return chrome.runtime.id; }
      };
    }

    // tabs
    if (chrome.tabs) {
      browserObj.tabs = {
        query: wrapAsyncFunction(chrome.tabs.query, chrome.tabs),
        sendMessage: wrapAsyncFunction(chrome.tabs.sendMessage, chrome.tabs),
        get: wrapAsyncFunction(chrome.tabs.get, chrome.tabs),
        create: wrapAsyncFunction(chrome.tabs.create, chrome.tabs),
        update: wrapAsyncFunction(chrome.tabs.update, chrome.tabs),
        remove: wrapAsyncFunction(chrome.tabs.remove, chrome.tabs),
        onUpdated: chrome.tabs.onUpdated,
        onActivated: chrome.tabs.onActivated,
        onRemoved: chrome.tabs.onRemoved
      };
    }

    // storage
    if (chrome.storage) {
      browserObj.storage = {
        local: {
          get: wrapAsyncFunction(chrome.storage.local.get, chrome.storage.local),
          set: wrapAsyncFunction(chrome.storage.local.set, chrome.storage.local),
          remove: wrapAsyncFunction(chrome.storage.local.remove, chrome.storage.local),
          clear: wrapAsyncFunction(chrome.storage.local.clear, chrome.storage.local)
        }
      };
      if (chrome.storage.sync) {
        browserObj.storage.sync = {
          get: wrapAsyncFunction(chrome.storage.sync.get, chrome.storage.sync),
          set: wrapAsyncFunction(chrome.storage.sync.set, chrome.storage.sync),
          remove: wrapAsyncFunction(chrome.storage.sync.remove, chrome.storage.sync),
          clear: wrapAsyncFunction(chrome.storage.sync.clear, chrome.storage.sync)
        };
      }
    }

    // action (MV3 — replaces browserAction / pageAction)
    if (chrome.action) {
      browserObj.action = {
        setIcon: wrapAsyncFunction(chrome.action.setIcon, chrome.action),
        setTitle: wrapAsyncFunction(chrome.action.setTitle, chrome.action),
        setPopup: wrapAsyncFunction(chrome.action.setPopup, chrome.action),
        setBadgeText: wrapAsyncFunction(chrome.action.setBadgeText, chrome.action),
        setBadgeBackgroundColor: wrapAsyncFunction(chrome.action.setBadgeBackgroundColor, chrome.action),
        onClicked: chrome.action.onClicked
      };
    }

    // commands
    if (chrome.commands) {
      browserObj.commands = {
        onCommand: chrome.commands.onCommand
      };
      if (chrome.commands.getAll) {
        browserObj.commands.getAll = wrapAsyncFunction(chrome.commands.getAll, chrome.commands);
      }
    }

    // i18n
    if (chrome.i18n) {
      browserObj.i18n = {
        getMessage: chrome.i18n.getMessage.bind(chrome.i18n),
        getAcceptLanguages: chrome.i18n.getAcceptLanguages
          ? wrapAsyncFunction(chrome.i18n.getAcceptLanguages, chrome.i18n)
          : undefined,
        getUILanguage: chrome.i18n.getUILanguage
          ? chrome.i18n.getUILanguage.bind(chrome.i18n)
          : undefined
      };
    }

    globalThis.browser = browserObj;
  }
})();
